  str_n18_16_name_desc = "—",
  str_n18_1_name_desc_long = "Setelah terbangun dari mimpi indahmu soal sukses besar, kamu ternyata harus membayar tagihan yang mahal dan membereskan banyak Eclipsite.",
  str_n18_2_name_desc_long = "Walaupun sudah dibantu oleh Bethel, perekrutannya tidak berjalan dengan mulus. Saat-saat buntu, tiga kandidat terakhir muncul untuk wawancara dan memberimu harapan lagi. Nina, Sanae, dan Minos mengusulkan untuk membagi semuanya menjadi dua tim untuk memperebutkan posisi tersebut.",
  str_n18_3_name_desc_long = "Untuk memusnahkan Eclipsite, meningkatkan manajemen Cloud Gardens, dan memperoleh penghasilan untuk melunasi utang, kamu berangkat ke Land of Fertility tempat Unique Tree tumbuh. Ketiga manajer yang punya potensi tersebut menunjukkan kemampuan spesialnya. Nina juga makin tertarik dengan Chubb, penghuni fantastis Cloud Gardens.",
